mapper.select:
select a.task_id, a.task_name, a.task_type as cType, a.task_state as cState, a.task_count, a.task_count-a.task_wait as cruise_data_state1, a.task_wait as cruise_data_state2, a.task_abnormal, a.execute_time, a.check_user, a.check_date, a.modify_state, a.task_wait,a.create_time, a.remark, a.weather FROM u_patrol_result a LEFT JOIN u_patrol_task_attr f ON a.task_id = f.task_id where 1 = 1 and a.task_name like concat('%',#{taskName, jdbcType=VARCHAR},'%')
and a.task_type = #{cType, jdbcType=INTEGER} and a.task_state = #{cState, jdbcType=INTEGER} and a.execute_time BETWEEN #{startDate, jdbcType=TIMESTAMP} AND #{endDate, jdbcType=TIMESTAMP}
and f.region_id IN
#{deviceIds,jdbcType=BIGINT}
and f.device_type = #{deviceType, jdbcType=INTEGER} and f.mete_type = #{meteType, jdbcType=VARCHAR} and f.custom_id = #{customId, jdbcType=VARCHAR} and a.remark != 1 and a.remark = 1
and a.task_state != 239 and a.task_state != 241 and a.task_state != 238 GROUP BY task_id order by a.execute_time desc

select distinct
a.task_id
FROM u_patrol_result a
LEFT JOIN u_patrol_task_attr f ON a.task_id = f.task_id
where 1 = 1
and a.task_name like
    concat('%',#{taskName, jdbcType=VARCHAR},'%')

and a.task_type = #{cType, jdbcType=INTEGER}
and a.task_state = #{cState, jdbcType=INTEGER}
and a.execute_time BETWEEN #{startDate, jdbcType=TIMESTAMP} AND
    #{endDate, jdbcType=TIMESTAMP}

and f.device_id IN

        #{deviceIds,jdbcType=BIGINT}


and f.device_type = #{deviceType, jdbcType=INTEGER}
and f.mete_type = #{meteType, jdbcType=VARCHAR}
and f.custom_id = #{customId, jdbcType=VARCHAR}
and a.check_user is null
and a.check_user is not null

and a.task_state != 239 and a.task_state != 241 and a.task_state != 238
GROUP BY task_id
order by a.execute_time desc

SELECT DISTINCT n.real_code, b.device_name, b.instance_name, b.cruise_data_id, b.cruise_type, b.result_num, b.result_desc, b.cruise_result, b.cruise_time, b.cruise_abnormal, b.remark, b.evaluation_state, b.check_user, b.check_date, b.picpath as pic_path, b.identify_result, b.identify_state, b.person_check, b.device_id, b.instance_id, e.device_mete_id, q.state_zero, q.state_one, q.high_limit1, q.high_limit2, q.high_limit3, q.high_limit4, q.low_limit1, q.low_limit2, q.low_limit3, q.low_limit4, q.unit, q.mete_kind, q.meter_type, q.mete_type, e.cruise_id as preset_id, k.camera_id, b.is_warn, q.alarm_state, q.alarm_level, q.is_temdif, n.device_type, b.voice_path, conf.db_value as dbValue, conf.f_value as fValue, region.region_name as edge_name, b.custom_name, b.device_point_id FROM u_patrol_data_result b LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device n on n.device_id = b.device_id LEFT JOIN t_std_devicemete q on q.device_mete_id = e.device_mete_id LEFT JOIN t_camera_preset k on k.preset_id = e.cruise_id left join t_voice_device voice on e.cruise_id = voice.voice_device_id left join t_voice_config conf on voice.config_id = conf.config_id left join t_std_region region on ifnull(n.edge_code,'0')=region.region_code and region.state=1 WHERE 1 = 1 and b.task_id = #{taskId,jdbcType=VARCHAR}
and n.device_type = #{deviceType, jdbcType=INTEGER} and b.is_warn = #{isWarn, jdbcType=INTEGER}
and b.cruise_type = #{cruiseType, jdbcType=INTEGER}
and b.cruise_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and b.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and e.custom_id = #{customId, jdbcType=VARCHAR}
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
ORDER BY b.cruise_time asc, b.instance_id asc, b.device_id asc

SELECT n.real_code, b.device_name, b.instance_name, b.cruise_type, b.result_num, b.cruise_result, b.cruise_time, b.cruise_abnormal, b.remark, b.evaluation_state, b.check_user, b.check_date, b.picpath as pic_path, b.identify_result, b.identify_state, b.person_check, b.device_id, q.device_point_id, b.instance_id, e.device_mete_id, q.state_zero, q.state_one, q.high_limit1, q.high_limit2, q.high_limit3, q.high_limit4, q.low_limit1, q.low_limit2, q.low_limit3, q.low_limit4, q.unit, q.mete_kind, q.meter_type, q.mete_type, e.cruise_id as preset_id, k.camera_id, -- b.end_time, b.is_warn, q.alarm_state, q.alarm_level, n.device_type, b.voice_path FROM u_patrol_result a LEFT JOIN u_patrol_data_result b on a.task_id = b.task_id LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device n on n.device_id = b.device_id LEFT JOIN t_std_devicemete q on q.device_mete_id = e.device_mete_id LEFT JOIN t_camera_preset k on k.preset_id = e.cruise_id WHERE 1 = 1 and b.cruise_data_id = #{taskResultId,jdbcType=VARCHAR}
and n.device_type = #{deviceType, jdbcType=INTEGER}
and b.cruise_type = #{cruiseType, jdbcType=INTEGER}
and cruise_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and b.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and e.custom_id = #{customId, jdbcType=VARCHAR}
and b.instance_name like concat('%',#{instanceName, jdbcType=VARCHAR},'%')
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
ORDER BY b.cruise_time DESC

select f.task_id, f.cruise_data_id, f.device_id, f.device_name, b.device_mete_id, f.instance_id, f.instance_name, b.mete_type, w.dict_note as mete_type_name, f.evaluation_state, x.dict_note as evaluation_state_name, f.result_num, f.result_desc as resultDesc, f.picpath as picPath, F.cruise_result, g.dict_note as cruise_result_name, f.cruise_time, a.real_code, f.person_check, f.identify_result, z.dict_note as identify_result_name, f.cruise_type, n.dict_note as dataType, b.custom_id, b.custom_name as componentName, a.up_region_name as intervalName, m.region_name as regionName, f.cruise_status as cruiseState, f.cruise_abnormal as cruiseAbnormal from u_patrol_data_result f LEFT JOIN t_cruise_point_instance h on h.instance_id = f.instance_id LEFT JOIN t_std_devicemete b on b.device_mete_id = h.device_mete_id LEFT JOIN t_dict_business g on g.dict_code = f.cruise_result and g.col_name = 'cruise_result' LEFT JOIN t_dict_business w on w.dict_code = b.mete_type and w.col_name = 'mete_type' LEFT JOIN t_dict_business x on x.dict_code = f.evaluation_state and x.col_name = 'evaluation_state' LEFT JOIN t_dict_business z on z.dict_code = f.identify_result and z.col_name = 'identify_result' LEFT JOIN t_std_device a on a.device_id = f.device_id LEFT JOIN t_std_region d on d.region_id = a.up_region_id LEFT JOIN t_std_region m on m.region_id = d.up_region_id LEFT JOIN t_dict_business n on n.dict_code = f.cruise_type and n.col_name = 'cruise_type' where 1 = 1 and f.device_id in
#{deviceIds, jdbcType=BIGINT}
and cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP} ORDER by cruise_time

